"""Worker Repair authority boundary.

Worker Repair is a maintenance-plane component for repairing Universal Worker
infrastructure. It does not participate in normal EDARSAHUB code creation.

This foundation intentionally contains validation/planning only. Git mutation
and runtime supervision are wired in later gates through existing canonical
lower-level guards rather than duplicating Universal Worker.
"""
from __future__ import annotations

from dataclasses import dataclass

from tools.mirror_sync.worker_maintenance_contract import (
    PROTECTED_UNIVERSAL_COMPONENTS,
    REPAIR_AUTHORITY,
    repair_scope_allowed,
)


@dataclass(frozen=True)
class RepairPlan:
    incident_id: str
    paths: tuple[str, ...]
    authority: str = REPAIR_AUTHORITY.role
    production_allowed: bool = False


def build_repair_plan(
    incident_id: str,
    paths: list[str] | tuple[str, ...],
) -> RepairPlan:
    incident = str(incident_id or "").strip()

    if not incident:
        raise ValueError("REPAIR_INCIDENT_ID_REQUIRED")

    clean_paths = tuple(str(path).strip() for path in paths)

    if not repair_scope_allowed(clean_paths):
        raise ValueError("REPAIR_SCOPE_FORBIDDEN")

    return RepairPlan(
        incident_id=incident,
        paths=clean_paths,
    )


def touches_protected_universal_component(plan: RepairPlan) -> bool:
    return bool(
        set(plan.paths).intersection(PROTECTED_UNIVERSAL_COMPONENTS)
    )


def repair_requires_independent_audit(plan: RepairPlan) -> bool:
    # Every Worker Repair mutation requires Worker Auditor certification.
    return True

"""Independent READ_ONLY Worker Auditor authority boundary.

Worker Auditor certifies Worker Repair evidence. It never mutates the
repository, Worker runtime, services, SQL, Production, or application code.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Any

from tools.mirror_sync.worker_maintenance_contract import (
    AUDITOR_AUTHORITY,
    auditor_scope_allowed,
)


@dataclass(frozen=True)
class AuditDecision:
    certified: bool
    reason: str
    production_touched: bool = False
    mutation_performed: bool = False


def audit_repair_result(result: dict[str, Any]) -> AuditDecision:
    paths = tuple(result.get("files_changed") or ())

    if result.get("production_touched") is not False:
        return AuditDecision(
            certified=False,
            reason="PRODUCTION_TOUCHED",
        )

    if not paths:
        return AuditDecision(
            certified=False,
            reason="NO_REPAIR_MUTATION_EVIDENCE",
        )

    if not auditor_scope_allowed(paths):
        return AuditDecision(
            certified=False,
            reason="REPAIR_SCOPE_OUTSIDE_WORKER_INFRASTRUCTURE",
        )

    if result.get("quality_gate") != "PASS":
        return AuditDecision(
            certified=False,
            reason="QUALITY_GATE_NOT_PASS",
        )

    if result.get("tests") != "PASS":
        return AuditDecision(
            certified=False,
            reason="TESTS_NOT_PASS",
        )

    if result.get("blockers") not in ([], None):
        return AuditDecision(
            certified=False,
            reason="BLOCKERS_PRESENT",
        )

    if result.get("git_sync_status") != "CERTIFIED_GIT_SYNC":
        return AuditDecision(
            certified=False,
            reason="GIT_SYNC_NOT_CERTIFIED",
        )

    return AuditDecision(
        certified=True,
        reason="CERTIFIED_WORKER_REPAIR",
    )


def auditor_can_mutate() -> bool:
    return AUDITOR_AUTHORITY.mutation_allowed

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]

if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from tools.mirror_sync.worker_auditor import (
    audit_repair_result,
    auditor_can_mutate,
)
from tools.mirror_sync.worker_maintenance_contract import (
    AUDITOR_AUTHORITY,
    REPAIR_AUTHORITY,
    repair_scope_allowed,
)
from tools.mirror_sync.worker_repair import (
    build_repair_plan,
    repair_requires_independent_audit,
)


def test_repair_and_auditor_are_distinct_authorities():
    assert REPAIR_AUTHORITY.role == "WORKER_REPAIR"
    assert REPAIR_AUTHORITY.mutation_allowed is True

    assert AUDITOR_AUTHORITY.role == "WORKER_AUDITOR"
    assert AUDITOR_AUTHORITY.mutation_allowed is False


def test_neither_role_can_touch_production():
    assert REPAIR_AUTHORITY.production_allowed is False
    assert AUDITOR_AUTHORITY.production_allowed is False


def test_neither_role_is_normal_development_worker():
    assert REPAIR_AUTHORITY.normal_development_jobs_allowed is False
    assert AUDITOR_AUTHORITY.normal_development_jobs_allowed is False


def test_repair_scope_is_worker_infrastructure_only():
    assert repair_scope_allowed(
        ["tools/mirror_sync/gate_chain_publisher.py"]
    )

    assert not repair_scope_allowed(
        ["frontend/src/App.jsx"]
    )

    assert not repair_scope_allowed(
        ["backend/modules/comercial/routes.py"]
    )


def test_repair_plan_requires_independent_audit():
    plan = build_repair_plan(
        "INCIDENT-1",
        ["tools/mirror_sync/gate_chain_publisher.py"],
    )

    assert repair_requires_independent_audit(plan) is True


def test_auditor_is_read_only():
    assert auditor_can_mutate() is False


def test_auditor_certifies_only_valid_worker_repair():
    decision = audit_repair_result(
        {
            "files_changed": [
                "tools/mirror_sync/gate_chain_publisher.py",
            ],
            "production_touched": False,
            "quality_gate": "PASS",
            "tests": "PASS",
            "blockers": [],
            "git_sync_status": "CERTIFIED_GIT_SYNC",
        }
    )

    assert decision.certified is True
    assert decision.reason == "CERTIFIED_WORKER_REPAIR"
    assert decision.mutation_performed is False
    assert decision.production_touched is False


def test_auditor_rejects_application_code_mutation():
    decision = audit_repair_result(
        {
            "files_changed": [
                "frontend/src/App.jsx",
            ],
            "production_touched": False,
            "quality_gate": "PASS",
            "tests": "PASS",
            "blockers": [],
            "git_sync_status": "CERTIFIED_GIT_SYNC",
        }
    )

    assert decision.certified is False


def test_auditor_rejects_production_touch():
    decision = audit_repair_result(
        {
            "files_changed": [
                "tools/mirror_sync/gate_chain_publisher.py",
            ],
            "production_touched": True,
            "quality_gate": "PASS",
            "tests": "PASS",
            "blockers": [],
            "git_sync_status": "CERTIFIED_GIT_SYNC",
        }
    )

    assert decision.certified is False
    assert decision.reason == "PRODUCTION_TOUCHED"
